'use strict';
// Dragones del puente de los dragones con el sprite aportado por el usuario (hoja 3x3 del dragón rojo).
// Se limpia el fondo, se reduce, se le pone contorno y se tiñe según el elemento (fuego, tierra, eléctrico, luz).
// Mientras la imagen carga se ven los dragones antiguos (por formas); al terminar se sustituyen.
const DRAGON_SHEET = 'data:image/webp;base64,';
const DRAGON_OUT = [14, 10, 12];
function dragonFrames(im, K){
  const c = document.createElement('canvas'); c.width = im.width; c.height = im.height;
  const g = c.getContext('2d', {willReadFrequently:true}); g.drawImage(im, 0, 0);
  const d = g.getImageData(0, 0, c.width, c.height), W = c.width, H = c.height, px = d.data;
  const lit = p => Math.min(px[p*4], px[p*4+1], px[p*4+2]) > 178 && Math.max(px[p*4], px[p*4+1], px[p*4+2]) - Math.min(px[p*4], px[p*4+1], px[p*4+2]) < 30;
  const bg = p => px[p*4+3] < 20 || lit(p);
  const seen = new Uint8Array(W*H), st = [];
  for(let x = 0; x < W; x++) st.push(x, x + (H-1)*W);
  for(let y = 0; y < H; y++) st.push(y*W, y*W + W - 1);
  while(st.length){ const p = st.pop(); if(seen[p] || !bg(p)) continue; seen[p] = 1; px[p*4+3] = 0; const x = p % W; if(x > 0) st.push(p-1); if(x < W-1) st.push(p+1); if(p >= W) st.push(p-W); if(p < W*(H-1)) st.push(p+W); }
  // bolsas claras encerradas (entre la cola y el cuerpo, bajo las alas)
  { const mk = new Uint8Array(W*H); for(let s = 0; s < W*H; s++){ if(mk[s] || px[s*4+3] < 20 || !lit(s)) continue; const comp = [s]; mk[s] = 1; for(let i = 0; i < comp.length; i++){ const p = comp[i], x = p % W; for(const q of [x > 0 ? p-1 : -1, x < W-1 ? p+1 : -1, p-W, p+W]) if(q >= 0 && q < W*H && !mk[q] && px[q*4+3] >= 20 && lit(q)){ mk[q] = 1; comp.push(q); } } if(comp.length > 120) for(const p of comp) px[p*4+3] = 0; } }
  // halo claro pegado al vacío
  for(let pass = 0; pass < 3; pass++){ const kill = []; for(let y = 1; y < H-1; y++) for(let x = 1; x < W-1; x++){ const p = y*W + x; if(px[p*4+3] < 20) continue; if((px[(p-1)*4+3] < 20 || px[(p+1)*4+3] < 20 || px[(p-W)*4+3] < 20 || px[(p+W)*4+3] < 20) && Math.min(px[p*4], px[p*4+1], px[p*4+2]) > 190) kill.push(p); } for(const p of kill) px[p*4+3] = 0; }
  const sat = p => { const mx = Math.max(px[p*4], px[p*4+1], px[p*4+2]), mn = Math.min(px[p*4], px[p*4+1], px[p*4+2]); return mx ? (mx - mn)/mx : 0; };
  const out = {}, cw = Math.floor(W/3), ch = Math.floor(H/3);
  for(const i of [0, 3, 5, 8]){
    const qx = (i % 3)*cw, qy = Math.floor(i/3)*ch, mk = new Uint8Array(W*H), comps = [];
    for(let y = qy; y < qy + ch; y++) for(let x = qx; x < qx + cw; x++){
      const s = y*W + x; if(mk[s] || px[s*4+3] < 20) continue;
      const comp = [s]; mk[s] = 1;
      for(let j = 0; j < comp.length; j++){ const p = comp[j], X = p % W, Y = (p - X)/W; for(const [nx, ny] of [[X-1, Y], [X+1, Y], [X, Y-1], [X, Y+1]]){ if(nx < qx || nx >= qx + cw || ny < qy || ny >= qy + ch) continue; const q = ny*W + nx; if(!mk[q] && px[q*4+3] >= 20){ mk[q] = 1; comp.push(q); } } }
      comps.push(comp);
    }
    comps.sort((a, b) => b.length - a.length);
    const bb = cp => { let x0 = W, x1 = 0, y0 = H, y1 = 0, ss = 0; for(const p of cp){ const x = p % W, y = (p - x)/W; if(x < x0) x0 = x; if(x > x1) x1 = x; if(y < y0) y0 = y; if(y > y1) y1 = y; ss += sat(p); } return {x0, x1, y0, y1, s:ss/cp.length}; };
    const body = bb(comps[0]), mg = i === 5 ? 90 : 25;   // las llamas del fotograma 5 pueden salir del cuerpo; las motas lejanas o claras se borran
    const keep = comps.filter((cp, n) => { if(n === 0) return true; const q = bb(cp); return (cp.length >= 600 || (cp.length >= 40 && q.s > .45)) && q.x1 > body.x0 - mg && q.x0 < body.x1 + mg && q.y1 > body.y0 - mg && q.y0 < body.y1 + mg; }) ; let x0 = W, x1 = 0, y0 = H, y1 = 0;
    const mkc = new Uint8Array(W*H); for(const cp of keep){ const b2 = bb(cp); x0 = Math.min(x0, b2.x0); x1 = Math.max(x1, b2.x1); y0 = Math.min(y0, b2.y0); y1 = Math.max(y1, b2.y1); for(const p of cp) mkc[p] = 1; }
    const sw = x1 - x0 + 1, sh = y1 - y0 + 1, ow = Math.ceil(sw*K) + 4, oh = Math.ceil(sh*K) + 4;
    const src = document.createElement('canvas'); src.width = sw; src.height = sh; const sg = src.getContext('2d'), sd = sg.createImageData(sw, sh);
    for(let y = 0; y < sh; y++) for(let x = 0; x < sw; x++){ const p = (y0 + y)*W + x0 + x; if(mkc[p]) sd.data.set(px.subarray(p*4, p*4+4), (y*sw + x)*4); }
    sg.putImageData(sd, 0, 0);
    const o = document.createElement('canvas'); o.width = ow; o.height = oh;
    const og = o.getContext('2d', {willReadFrequently:true}); og.imageSmoothingEnabled = true; og.imageSmoothingQuality = 'high'; og.drawImage(src, 2, 2, sw*K, sh*K);
    const id = og.getImageData(0, 0, ow, oh), a = id.data;
    for(let j = 3; j < a.length; j += 4) a[j] = a[j] > 120 ? 255 : 0;
    const op = new Uint8Array(ow*oh); for(let j = 0; j < ow*oh; j++) op[j] = a[j*4+3] ? 1 : 0;
    for(let y = 0; y < oh; y++) for(let x = 0; x < ow; x++){ const j = y*ow + x; if(op[j]) continue; if((x > 0 && op[j-1]) || (x < ow-1 && op[j+1]) || (y > 0 && op[j-ow]) || (y < oh-1 && op[j+ow])){ a[j*4] = DRAGON_OUT[0]; a[j*4+1] = DRAGON_OUT[1]; a[j*4+2] = DRAGON_OUT[2]; a[j*4+3] = 255; } }
    og.putImageData(id, 0, 0);
    out[i] = {c:o, ax:Math.round(((body.x0 + body.x1)/2 - x0)*K + 2), ay:Math.round((body.y1 - y0)*K + 2) - 2};
  }
  return out;
}
// tiñe una copia del fotograma: el rojo se lleva al tono del elemento y el resto de tonos se acerca a él
function dragonTint(cv, t){
  const o = document.createElement('canvas'); o.width = cv.width; o.height = cv.height;
  const g = o.getContext('2d', {willReadFrequently:true}); g.drawImage(cv, 0, 0);
  const id = g.getImageData(0, 0, o.width, o.height), a = id.data;
  for(let i = 0; i < a.length; i += 4){
    if(!a[i+3]) continue;
    const r = a[i]/255, gg = a[i+1]/255, b = a[i+2]/255, mx = Math.max(r, gg, b), mn = Math.min(r, gg, b), l = (mx + mn)/2, dd = mx - mn;
    if(dd < .06) continue;   // contorno y grises
    let h = mx === r ? ((gg - b)/dd + 6) % 6 : mx === gg ? (b - r)/dd + 2 : (r - gg)/dd + 4; h *= 60;
    const s = dd/(1 - Math.abs(2*l - 1));
    const off = (h > 180 ? h - 360 : h) + 5;   // el rojo del dragón ronda los -5°
    const nh = (t.h + off*t.spread + 360) % 360, ns = Math.min(1, s*t.s), nl = Math.min(.96, Math.max(.04, l*t.l + t.add));
    const C = (1 - Math.abs(2*nl - 1))*ns, X = C*(1 - Math.abs((nh/60) % 2 - 1)), m = nl - C/2;
    const [rr, g2, bb] = nh < 60 ? [C, X, 0] : nh < 120 ? [X, C, 0] : nh < 180 ? [0, C, X] : nh < 240 ? [0, X, C] : nh < 300 ? [X, 0, C] : [C, 0, X];
    a[i] = Math.round((rr + m)*255); a[i+1] = Math.round((g2 + m)*255); a[i+2] = Math.round((bb + m)*255);
  }
  g.putImageData(id, 0, 0); return o;
}
// boca = punto más a la derecha de la cabeza (hocico) del fotograma, relativo al ancla
function dragonMouth(f){
  const c = f.c, W = c.width, H = c.height, d = c.getContext('2d').getImageData(0, 0, W, H).data;
  let y0 = H, y1 = 0, sx = 0, n = 0;
  for(let y = 0; y < H; y++) for(let x = 0; x < W; x++) if(d[(y*W + x)*4 + 3] > 100){ if(y < y0) y0 = y; if(y > y1) y1 = y; }
  for(let y = y0; y < y0 + (y1 - y0)*.22; y++) for(let x = W*.3; x < W*.7; x++) if(d[(y*W + (x|0))*4 + 3] > 100){ sx += x; n++; }
  return {x:(n ? sx/n : W/2) - f.ax, y:y0 + (y1 - y0)*.34 - f.ay};
}
const DRAGON_TINT = {earth:{h:28, spread:.35, s:.62, l:.95, add:0, fl:['#5a3a1c', '#8a6234', '#c09458', '#ecd9a4']}, elec:{h:212, spread:.25, s:1, l:1.06, add:.02, fl:['#2a4ac8', '#3a90ff', '#aee0ff', '#ffffff']}, air:{h:205, spread:.2, s:.32, l:1.75, add:.08, fl:['#7aa0c0', '#b8dcf0', '#e8f8ff', '#ffffff']}, ice:{h:192, spread:.2, s:.95, l:1.35, add:.05, fl:['#2a78c0', '#6ac8f0', '#c8f4ff', '#ffffff']}, thunder:{h:272, spread:.3, s:.85, l:1.1, add:.02, fl:['#5a2ab0', '#a060ff', '#e0c0ff', '#ffffff']}, light:{h:50, spread:.2, s:1.05, l:1.55, add:.05, fl:['#d8a820', '#ffe060', '#fff6b8', '#ffffff']}};
{
  const im = new Image();
  im.onload = () => {
    const set = (id, K, tint, atk) => {
      const F = dragonFrames(im, K), pick = [F[3], F[8], F[atk]];
      MON_ART[id] = {fr:pick.map(f => SP(tint ? dragonTint(f.c, tint) : f.c, f.ax, f.ay))};
      MON_ART[id].mouth = dragonMouth(pick[0]);
      MON_ART[id].flash = MON_ART[id].fr.map(s => { const cv = document.createElement('canvas'); cv.width = s.c.width; cv.height = s.c.height; const g = cv.getContext('2d'); g.drawImage(s.c, 0, 0); g.globalCompositeOperation = 'source-in'; g.fillStyle = '#fff'; g.fillRect(0, 0, cv.width, cv.height); return {c:cv, ax:s.ax, ay:s.ay}; });
    };
    set('ignisdr', .4, null, 5);   // el dragón de fuego usa el fotograma con la llamarada al atacar
    set('dgearth', .29, DRAGON_TINT.earth, 0); set('dgelec', .29, DRAGON_TINT.elec, 0); set('dglight', .29, DRAGON_TINT.light, 0); set('dgair', .29, DRAGON_TINT.air, 0);
    set('glaciusdr', .4, DRAGON_TINT.ice, 0); set('voltusdr', .4, DRAGON_TINT.thunder, 0);
  };
  im.src = DRAGON_SHEET;
}

// aliento de cada dragón: mientras prepara o lanza el aliento suelta un chorro grande de partículas desde el hocico (el de fuego lleva además la llamarada del sprite)
const DRAGON_BREATH = {
  ignisdr:{col:['#ff3a1a', '#ff7a2a', '#ffb83a', '#ffe27a', '#ffffff'], spd:[260, 560], sz:[10, 26], n:16},
  dgearth:{col:DRAGON_TINT.earth.fl, spd:[200, 440], sz:[10, 24], n:16},
  dgair:{col:DRAGON_TINT.air.fl, spd:[340, 620], sz:[8, 20], n:18, swirl:true},
  dgelec:{col:DRAGON_TINT.elec.fl, spd:[300, 580], sz:[8, 18], n:18, jit:true},
  dglight:{col:DRAGON_TINT.light.fl, spd:[240, 480], sz:[10, 24], n:18},
  glaciusdr:{col:DRAGON_TINT.ice.fl, spd:[280, 540], sz:[10, 26], n:18},
  voltusdr:{col:DRAGON_TINT.thunder.fl, spd:[320, 600], sz:[8, 20], n:18, jit:true},
};
// los dragones normales también lanzan un aliento real en cono (los hermanos usan su ataque «Aliento de dragón»)
const DRAGON_CONE = {
  dgearth:{name:'¡Aliento de tierra!', col:'#d8b878', fx:m => { if(Math.random() < .45){ P.poisonT = Math.max(P.poisonT || 0, 7); addText(P.x, P.y - 62, '¡Envenenado!', '#9ad86a', 8); } }},
  dgair:{name:'¡Aliento de aire!', col:'#d8f0ff', fx:m => { if(Math.random() < .7){ P.slowT = Math.max(P.slowT || 0, 3); addText(P.x, P.y - 62, '¡Ralentizado!', '#a0d8ff', 8); } }},
  dgelec:{name:'¡Aliento eléctrico!', col:'#ffe84a', fx:m => { if(Math.random() < .4 && !legendOn('yetiheart')){ P.stunT = Math.max(P.stunT || 0, .7); addText(P.x, P.y - 62, '¡Aturdido!', '#ffe08a', 8); } }},
  dglight:{name:'¡Aliento de luz!', col:'#fff4b0', fx:m => { if(Math.random() < .5){ P.weakT = Math.max(P.weakT || 0, 4); addText(P.x, P.y - 62, '¡Debilitado!', '#ffe84a', 8); } }},
};
{
  const _tick = monAffixTick;
  monAffixTick = function(m, dt){
    const C = DRAGON_CONE[m.type];
    if(C && m.aggro && !m.dying && !P.dead){
      m.brCd = (m.brCd ?? rand(2, 4)) - dt;
      if(m.brW > 0){
        m.brW -= dt; m.face = P.x >= m.x ? 1 : -1; m.aim = m.brAim = angTo(m);
        if(m.brW <= 0){ m.brF = .55; m.brT = 0; }
      } else if(m.brF > 0){
        m.brF -= dt; m.brT -= dt;
        if(m.brT <= 0){ m.brT = .2; bossSlash(m, 280, .5, .75, [C.col, '#ffffff'], () => C.fx(m)); }
      } else if(m.brCd <= 0 && m.stunT <= 0 && m.freezeT <= 0 && Math.hypot(P.x - m.x, P.y - m.y) < 250 && los(G.sc, m.x, m.y, P.x, P.y)){
        m.brW = .8; m.brCd = rand(6, 9); m.brAim = angTo(m); addText(m.x, m.y - 90, C.name, C.col, 8, -20);
      }
    }
    return _tick(m, dt);
  };
}
const _drawUndeadDragon = drawUndead;
drawUndead = function(m, vis){
  _drawUndeadDragon(m, vis);
  const B = DRAGON_BREATH[m.type], real = m.brW > 0 || m.brF > 0;
  if(!B || !(m.prepT > 0 || real) || m.dying || !MON_ART[m.art]) return;
  const mo = MON_ART[m.art].mouth || {x:20, y:-20}, sc = m.scale || 1, ox = m.face*(mo.x + 7)*sc, oy = mo.y*sc;
  const k = (m.brW > 0 ? .5 : 1), n = Math.max(1, Math.round(B.n*k));
  for(let i = 0; i < n; i++){
    let a = (m.face > 0 ? .62 : Math.PI - .62) + rand(-.3, .3)*m.face;
    if(real && m.brAim !== undefined){ a = m.brAim + rand(-.3, .3); }   // el chorro sigue hacia donde apunta el aliento
    const sp = rand(B.spd[0], B.spd[1])*2.4;
    G.parts.push({x:m.x + ox, y:m.y + oy, vx:Math.cos(a)*sp + (B.jit ? rand(-40, 40) : 0), vy:Math.sin(a)*sp*.9 + (B.swirl ? rand(-50, 50) : 0), life:.7, max:.7, size:rand(B.sz[0], B.sz[1]), col:pick(B.col)});
  }
};
